// Generated by build.mjs — do not edit dist/sw.js by hand.
// Cache-first for everything: alpine passes have no coverage, and a stale
// page is always better than no page. A new build ships a new CACHE name,
// which wipes the old one on activate.

const CACHE = 'roadbook-__VERSION__';
const BASE = __BASE__;
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // addAll is all-or-nothing; cache individually so one bad URL cannot
    // leave the rider with no offline copy at all.
    await Promise.all(PRECACHE.map(async (url) => {
      try {
        await cache.add(new Request(url, { cache: 'reload' }));
      } catch (error) {
        console.warn('Précache impossible :', url, error);
      }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.map((name) => (name === CACHE ? null : caches.delete(name))));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith((async () => {
    const cached = await caches.match(request, { ignoreSearch: true });
    if (cached) {
      // Refresh in the background so the next stop shows the latest edit.
      event.waitUntil(refresh(request));
      return cached;
    }

    try {
      const response = await fetch(request);
      if (response.ok && response.type === 'basic') {
        const cache = await caches.open(CACHE);
        await cache.put(request, response.clone());
      }
      return response;
    } catch (error) {
      // Offline and never cached: fall back to the home page for navigations.
      if (request.mode === 'navigate') {
        const home = await caches.match(BASE, { ignoreSearch: true })
          || await caches.match(BASE + 'index.html', { ignoreSearch: true });
        if (home) return home;
      }
      throw error;
    }
  })());
});

async function refresh(request) {
  try {
    const response = await fetch(request);
    if (response.ok && response.type === 'basic') {
      const cache = await caches.open(CACHE);
      await cache.put(request, response);
    }
  } catch (error) {
    // Offline: keep what we have.
  }
}
